  const perfEditor=canWrite()?`<div class='dpCard'><div class='dpCardHead'><div><h3>POST PERFORMANCE</h3><p>Attach published Pulse content to this saved report, then enter post-level numbers. Ranking only compares posts using a common metric.</p></div><span class='pill'>${(m.performance||[]).length} ATTACHED</span></div>${attached||''}${available?`<details class='dpContentPicker'><summary>ADD PUBLISHED CONTENT (${(m.candidates||[]).filter(c=>!c.attached).length})</summary>${available}</details>`:(!attached?`<div class='empty'>No published Pulse content matches this report's client, campaign, platforms and dates.</div>`:'')}</div>`:'';
  return `<div class='dpCard'><div class='dpCardHead'><div><h3>COMMUNITY ACTIVITY</h3><p>Automatically pulled from Engagement and Listening entries already saved in Digital Pulse for this client/campaign and period.</p></div><span class='pill'>LIVE LOGS</span></div>${community}</div><div class='dpCard'><div class='dpCardHead'><div><h3>TOP CONTENT</h3><p>Strongest and weakest comparable published posts from post-level performance attached to this report.</p></div><span class='pill'>M3</span></div>${rankHtml}</div>${perfEditor}<div class='dpCard'><div class='dpCardHead'><div><h3>ISSUES / CASE SIGNALS</h3><p>Report-safe issue summaries from Digital Pulse. Private Case workspaces remain protected by existing Cases permissions.</p></div><span class='pill'>${(m.issues||[]).length}</span></div>${issues}</div>`;
