function reportIntelligenceHtml(){
  const x=state.reportIntelligence;if(!state.reportLoadedId)return '';
  if(!x)return `<div class='dpCard'><div class='dpLoading'><span class='dpSpinner'></span><div><b>Building report intelligence…</b></div></div></div>`;
  if(x.error)return `<div class='dpCard'><div class='empty'>${esc(x.error)}</div></div>`;
  const compare=x.comparisonRange?`${esc(x.comparisonRange.startDate)} → ${esc(x.comparisonRange.endDate)}`:'No comparison selected';
  const compareState=x.comparisonRange?(x.comparisonReport?`Matched saved report · ${compare}`:`No saved report found for ${compare}`):'Comparison disabled';
  const cards=(x.kpis||[]).map(k=>{
    const goal=k.goal&&Number.isFinite(Number(k.goal.weeklyTarget))?`<div class='dpGoalLine'><span>WEEKLY GOAL</span><b>${esc(reportFormatValue(k.goal.weeklyTarget,k.unit))}</b>${Number.isFinite(Number(k.goalProgress))?`<em>${Math.round(Number(k.goalProgress))}%</em>`:''}</div>`:'';
    return `<div class='dpIntelMetric'><span>${esc(k.metric)}</span><b>${esc(reportFormatValue(k.value,k.unit))}</b><small class='dpTrend ${reportTrendClass(k)}'>${esc(reportDeltaLabel(k))}</small>${goal}</div>`;
  }).join('')||`<div class='empty'>No KPI values are available in this saved report.</div>`;
  const platforms=(x.platforms||[]).map(p=>`<div class='dpPlatformCard'><h4>${esc(p.platform)}</h4>${(p.metrics||[]).map(m=>`<div class='dpPlatformMetric'><span>${esc(m.metric)}</span><b>${esc(reportFormatValue(m.value,m.unit))}</b><small class='dpTrend ${reportTrendClass(m)}'>${esc(reportDeltaLabel(m))}</small></div>`).join('')}</div>`).join('')||`<div class='empty'>No platform breakdown available.</div>`;
  const community=(x.community||[]).map(c=>`<div class='dpCommunityStat'><span>${esc(c.metric)}</span><b>${esc(reportFormatValue(c.value,c.unit))}</b></div>`).join('')||`<div class='empty'>Add Community Care or Sentiment metrics to populate this section.</div>`;
  const n=x.narrative||{};
  return `<div class='dpIntelHeader'><div><span class='dpEyebrow'>SAVED REPORT INTELLIGENCE</span><h2>${esc(x.brand||x.clientName||'Client')} · ${esc(x.reportType||'Report')}</h2><p>${esc(x.startDate)} → ${esc(x.endDate)}${x.campaign?' • '+esc(x.campaign):''}</p></div><span class='pill'>M3 INTELLIGENCE</span></div>
  <div class='dpCompareStatus'>${esc(compareState)}</div>
  <div class='dpIntelGrid'>${cards}</div>
  <div class='dpCard'><div class='dpCardHead'><div><h3>PLATFORM BREAKDOWN</h3><p>The same saved metrics, side by side by platform.</p></div></div><div class='dpPlatformBreakdown'>${platforms}</div></div>
  ${reportM3Html(x)}<div class='dpGrid'><div class='dpCard'><div class='dpCardHead'><div><h3>REPORTED COMMUNITY METRICS</h3><p>Optional Community Care and Sentiment metric rows saved directly in this report.</p></div></div><div class='dpCommunityGrid'>${community}</div></div>
  <div class='dpCard'><div class='dpCardHead'><div><h3>REPORT SUMMARY</h3><p>The Digital Team's saved interpretation, not AI-generated claims.</p></div></div>
  <div class='dpNarrative'><div><span>WHAT HAPPENED</span><p>${esc(n.whatHappened||'No summary entered.')}</p></div><div><span>WHY</span><p>${esc(n.why||'No explanation entered.')}</p></div><div><span>NEXT STEPS</span><p>${esc(n.nextSteps||'No next steps entered.')}</p></div></div></div></div>`;
}
